// ================================================================================================
// [Phase 4, P0.2] TC14: decision lag, the race, a reorg, a worker restart
// ================================================================================================
//
// Host URL labels `p02.<run>.legacy-direct.<case>.isAllowed.<fault>` tell fault_proxy.py (run with --heads,
// --signal-dir and --delay) what to do with that request's isAllowed calls: `control` passes them through; `hold`
// forwards the call at once, holds its true answer for --delay seconds and writes <signal dir>/<label>.hold
// ({t_upstream, head}) when the hold starts. Env (set by run_p02.sh): P02_RUN, P02_SIGNAL_DIR.

fn p02_run() -> String {
    std::env::var("P02_RUN").unwrap_or_else(|_| "r1".to_string())
}

fn p02_unix_now() -> f64 {
    SystemTime::now().duration_since(UNIX_EPOCH).map(|d| d.as_secs_f64()).unwrap_or(0.0)
}

/// Waits until the proxy holds `n` isAllowed calls of `label` (the direct legacy check makes two at once: user and
/// contract); returns the signal `{n, t_upstream, head}` of the latest one.
async fn p02_wait_hold(label: &str, n: u64, timeout: Duration) -> anyhow::Result<serde_json::Value> {
    let path = PathBuf::from(env("P02_SIGNAL_DIR")?).join(format!("{label}.hold"));
    let start = Instant::now();
    loop {
        if let Ok(text) = std::fs::read_to_string(&path) {
            if let Ok(v) = serde_json::from_str::<serde_json::Value>(&text) {
                if v["n"].as_u64().unwrap_or(0) >= n {
                    return Ok(v);
                }
            }
        }
        ensure!(start.elapsed() < timeout, "no hold signal for {label}");
        tokio::time::sleep(Duration::from_millis(20)).await;
    }
}

/// A legacy direct request, inserted (status `pending`) and not yet picked up.
struct P02Req {
    id: U256,
    tx_hash: B256,
    calldata: Vec<u8>,
}

/// One case's result, logged as `P02-RESULT`; a mismatch with `expect` is collected, the test fails at the end.
#[allow(clippy::too_many_arguments)]
fn p02_log(
    label: &str,
    case: &str,
    expect: Outcome,
    observed: &anyhow::Result<(Outcome, usize, Option<i16>, String)>,
    min_hits: usize,
    extra: &str,
    mismatches: &mut Vec<String>,
) {
    match observed {
        Ok((o, hits, ec, status)) => {
            info!(
                "P02-RESULT label={label} version={VERSION} case={case} expected={expect:?} observed={o:?} \
                kms_mock_hits={hits} error_counter={} status={status} {extra}",
                ec.map(|e| e.to_string()).unwrap_or_else(|| "-".into()),
            );
            let ok = match expect {
                Outcome::Rejected => *o == Outcome::Rejected && *hits == 0,
                Outcome::Forwarded => *o == Outcome::Forwarded && *hits >= min_hits,
            };
            if !ok {
                mismatches.push(format!("{label}: expected {expect:?}, observed {o:?} (kms hits {hits})"));
            }
        }
        Err(e) => {
            info!(
                "P02-RESULT label={label} version={VERSION} case={case} expected={expect:?} observed=HarnessError \
                kms_mock_hits=- error_counter=- status=- {extra} error=\"{e:#}\""
            );
            mismatches.push(format!("{label}: harness error {e:#}"));
        }
    }
}

use alloy::providers::RootProvider;
use fhevm_host_bindings::acl::ACL::ACLInstance;
use std::collections::HashMap;

/// The worker's host-chain provider as production builds it on main (`connect_to_rpc_node_with_bounds`): an HTTP
/// client bounded by `Config::default().host_rpc_call_timeout` (10 s; the P0.2 hold is shorter).
fn p02_host_contracts(chain_id: u64, acl: Address, url: Url) -> HashMap<u64, ACLInstance<RootProvider>> {
    let http_client = alloy::transports::http::reqwest::Client::builder()
        .timeout(Config::default().host_rpc_call_timeout)
        .build()
        .expect("reqwest client");
    let transport = alloy::transports::http::Http::with_client(http_client, url);
    let is_local = transport.guess_local();
    let client = alloy::rpc::client::RpcClient::new(transport, is_local);
    let provider = ProviderBuilder::new().disable_recommended_fillers().connect_client(client);
    HashMap::from([(chain_id, ACL::new(acl, provider))])
}

impl<'a> RequestHarness<'a> {
    /// Inserts a legacy direct request of `user` (main), as `run_legacy` does, without starting a worker.
    async fn p02_insert(&self, db: &Pool<Postgres>, user: Address) -> anyhow::Result<P02Req> {
        let c = self.acl.dapp;
        let calldata = userDecryptionRequestCall {
            ctHandleContractPairs: vec![CtHandleContractPair { ctHandle: self.handle, contractAddress: c }],
            contractsInfo: ContractsInfo { chainId: U256::from(self.env.chain_id), addresses: vec![c] },
            userAddress: user,
            ..Default::default()
        }
        .abi_encode();
        let tx_hash = rand_digest();
        let request = insert_rand_request(
            db,
            TestEventType::UserDecryption,
            InsertRequestOptions::new().with_ct_handles(vec![self.handle]).with_tx_hash(tx_hash),
        )
        .await?;
        let ProtocolEventKind::UserDecryption(request) = request else {
            bail!("unexpected request kind");
        };
        sqlx::query("UPDATE user_decryption_requests SET user_address = $1 WHERE decryption_id = $2")
            .bind(user.as_slice())
            .bind(request.decryptionId.as_le_slice())
            .execute(db)
            .await?;
        Ok(P02Req { id: request.decryptionId, tx_hash, calldata })
    }

    /// Starts a fresh unmodified worker (its own gateway and KMS mocks) for the pending request `r`.
    async fn p02_start(
        &self,
        db: &Pool<Postgres>,
        r: &P02Req,
        label: &str,
        cfg: &RunCfg,
    ) -> anyhow::Result<(MockServer, tokio::task::JoinHandle<()>, CancellationToken)> {
        let asserter = Asserter::new();
        mock_copro_registry_load(&asserter, &self.s3_base_url);
        for _ in 0..cfg.max_attempts {
            asserter.push_success(&mock_gateway_tx(r.tx_hash, r.calldata.clone())?);
        }
        let gateway_mock_provider =
            ProviderBuilder::new().disable_recommended_fillers().connect_mocked_client(asserter);
        let kms_server = start_kms_mock().await?;
        let config = self.config(&kms_server, cfg);
        let acl_contracts = p02_host_contracts(self.env.chain_id, self.acl.acl, self.env.tagged_host_url(label)?);
        let kms_worker = init_kms_worker(config, gateway_mock_provider, acl_contracts, db).await?;
        let cancel_token = CancellationToken::new();
        let task = tokio::spawn(kms_worker.start(cancel_token.clone()));
        Ok((kms_server, task, cancel_token))
    }
}

/// Waits for the outcome of `id`, stops the worker: (outcome, KMS-mock hits, error_counter, status).
async fn p02_finish(
    db: &Pool<Postgres>,
    id: U256,
    kms_server: &MockServer,
    task: tokio::task::JoinHandle<()>,
    cancel: CancellationToken,
    cfg: &RunCfg,
) -> anyhow::Result<(Outcome, usize, Option<i16>, String)> {
    let outcome = wait_for_outcome(db, id, cfg.outcome_timeout).await;
    if matches!(outcome, Ok((Outcome::Rejected, _))) {
        tokio::time::sleep(cfg.late_wait).await;
    }
    let hits = total_hits(kms_server);
    cancel.cancel();
    task.await.map_err(|e| anyhow!("kms-worker task: {e}"))?;
    let (observed, _) = outcome?;
    let (ec, status): (i16, String) = sqlx::query_as(
        "SELECT error_counter, status::text FROM user_decryption_requests WHERE decryption_id = $1",
    )
    .bind(id.as_le_slice())
    .fetch_one(db)
    .await?;
    Ok((observed, hits, Some(ec), status))
}

#[rstest]
#[timeout(Duration::from_secs(1800))]
#[tokio::test]
async fn p02_decision_lag() -> anyhow::Result<()> {
    let log_guard = init_tracing();
    let env = Env::load()?;
    let run = p02_run();
    let a = Accounts::load(&env).await?;
    let acl = deploy_acl(&env, AclKind::Level0, a.owner).await?;
    let handle = make_handle(env.chain_id);
    let keys = LocalKeys::new()?;
    setup_grants(&acl, &a, &keys, handle).await?;
    // One subject per case: anvil accounts 4..8, each granted the handle.
    let accounts = ProviderBuilder::new().connect_http(env.anvil_url.clone()).get_accounts().await?;
    let (r_after, r_race, r_reorg, r_restart, r_sent) = (accounts[4], accounts[5], accounts[6], accounts[7], accounts[8]);
    for r in [r_after, r_race, r_reorg, r_restart, r_sent] {
        acl.grant(handle, r).await?;
    }
    info!("P02-ACCOUNTS after={r_after} race={r_race} reorg={r_reorg} restart={r_restart} sent={r_sent}");

    let test_instance = TestInstanceBuilder::default()
        .with_tracing(Some(log_guard))
        .with_db(DbInstance::setup_external().await?)
        .build();
    let db = test_instance.db();
    let rh = RequestHarness::new(&env, &acl, AclKind::Level0, handle).await?;
    let cfg = RunCfg::harness();
    info!(
        "P02-CONFIG version={VERSION} run={run} max_attempts={} fast_polling_ms={} view_block=latest",
        cfg.max_attempts,
        cfg.fast_polling.as_millis()
    );
    let mut mismatches = Vec::new();
    let head = |p: &DynProvider| {
        let p = p.clone();
        async move { p.get_block_number().await.map_err(anyhow::Error::from) }
    };

    // ---------------------------------------------------------------- after: retired at N, request after N
    retire(&acl, r_after, "p02-after", "p02").await?;
    let n = head(&acl.provider).await?;
    let label = format!("p02.{run}.legacy-direct.after.isAllowed.control");
    let req = rh.p02_insert(db, r_after).await?;
    let (kms, task, cancel) = rh.p02_start(db, &req, &label, &cfg).await?;
    let res = p02_finish(db, req.id, &kms, task, cancel, &cfg).await;
    p02_log(&label, "after", Outcome::Rejected, &res, 2, &format!("retire_block={n}"), &mut mismatches);

    // ---------------------------------------------------------------- race: evaluated before N, used after N
    let label = format!("p02.{run}.legacy-direct.race.isAllowed.hold");
    let req = rh.p02_insert(db, r_race).await?;
    let (kms, task, cancel) = rh.p02_start(db, &req, &label, &cfg).await?;
    let hold = p02_wait_hold(&label, 2, Duration::from_secs(60)).await?;
    retire(&acl, r_race, "p02-race", "p02").await?;
    let n = head(&acl.provider).await?;
    let t_retired = p02_unix_now();
    let res = p02_finish(db, req.id, &kms, task, cancel, &cfg).await;
    let t_outcome = p02_unix_now();
    
    p02_log(
        &label,
        "race",
        Outcome::Forwarded,
        &res,
        2,
        &format!(
            "eval_head={} retire_block={n} t_eval={} t_retired={t_retired:.6} t_outcome_seen={t_outcome:.6}",
            hold["head"], hold["t_upstream"]
        ),
        &mut mismatches,
    );

    // ---------------------------------------------------------------- reorg: the retirement block is rolled back
    retire(&acl, r_reorg, "p02-reorg", "p02").await?;
    let n = head(&acl.provider).await?;
    let label = format!("p02.{run}.legacy-direct.reorg-before.isAllowed.control");
    let req = rh.p02_insert(db, r_reorg).await?;
    let (kms, task, cancel) = rh.p02_start(db, &req, &label, &cfg).await?;
    let res = p02_finish(db, req.id, &kms, task, cancel, &cfg).await;
    p02_log(&label, "reorg-before", Outcome::Rejected, &res, 2, &format!("retire_block={n}"), &mut mismatches);
    let _: serde_json::Value = acl.provider.raw_request("anvil_rollback".into(), (1u64,)).await?;
    let n_after = head(&acl.provider).await?;
    let still = IAclLevel0::new(acl.acl, &acl.provider).isAccountRetired(r_reorg).call().await?;
    info!("P02-REORG anvil_rollback(1): head {n} -> {n_after}, isAccountRetired(reorg subject)={still}");
    ensure!(n_after + 1 == n && !still, "the rollback did not remove the retirement block");
    let label = format!("p02.{run}.legacy-direct.reorg-after.isAllowed.control");
    let req = rh.p02_insert(db, r_reorg).await?;
    let (kms, task, cancel) = rh.p02_start(db, &req, &label, &cfg).await?;
    let res = p02_finish(db, req.id, &kms, task, cancel, &cfg).await;
    
    p02_log(&label, "reorg-after", Outcome::Forwarded, &res, 2, &format!("rolled_back_block={n} head={n_after}"), &mut mismatches);

    // ---------------------------------------------------------------- restart (a): stopped mid-check
    let label_a = format!("p02.{run}.legacy-direct.restart-a.isAllowed.hold");
    let req = rh.p02_insert(db, r_restart).await?;
    let (kms_a, task_a, cancel_a) = rh.p02_start(db, &req, &label_a, &cfg).await?;
    let hold = p02_wait_hold(&label_a, 2, Duration::from_secs(60)).await?;
    // Worker A stops picking; its in-flight check (a spawned task) loses its connection without an answer, as a
    // stopped worker's call would. The attempt then fails and the row leaves `under_process`.
    cancel_a.cancel();
    task_a.await.map_err(|e| anyhow!("worker A task: {e}"))?;
    std::fs::write(PathBuf::from(std::env::var("P02_SIGNAL_DIR")?).join(format!("{label_a}.abort")), b"1")?;
    let started = Instant::now();
    let status_a: String = loop {
        let s: String = sqlx::query_scalar("SELECT status::text FROM user_decryption_requests WHERE decryption_id = $1")
            .bind(req.id.as_le_slice())
            .fetch_one(db)
            .await?;
        if s != "under_process" {
            break s;
        }
        ensure!(started.elapsed() < Duration::from_secs(30), "worker A's attempt did not end");
        tokio::time::sleep(Duration::from_millis(50)).await;
    };
    tokio::time::sleep(Duration::from_millis(500)).await;
    let hits_a = total_hits(&kms_a);
    // Had worker A died with the row `under_process`, the tx-sender's recovery routine would unlock it; same update.
    let unlocked = sqlx::query(
        "UPDATE user_decryption_requests SET status = 'pending' WHERE decryption_id = $1 AND status = 'under_process'",
    )
    .bind(req.id.as_le_slice())
    .execute(db)
    .await?
    .rows_affected();
    retire(&acl, r_restart, "p02-restart", "p02").await?;
    let n = head(&acl.provider).await?;
    let label_b = format!("p02.{run}.legacy-direct.restart-b.isAllowed.control");
    let (kms, task, cancel) = rh.p02_start(db, &req, &label_b, &cfg).await?;
    let res = p02_finish(db, req.id, &kms, task, cancel, &cfg).await;
    p02_log(
        &label_b,
        "restart-mid-check",
        Outcome::Rejected,
        &res,
        2,
        &format!(
            "worker_a_eval_head={} worker_a_kms_hits={hits_a} status_after_a={status_a} unlocked={unlocked} retire_block={n}",
            hold["head"]
        ),
        &mut mismatches,
    );
    if hits_a != 0 {
        mismatches.push(format!("{label_a}: worker A reached the KMS mock ({hits_a})"));
    }

    // ---------------------------------------------------------------- restart (b): already sent to the KMS
    for retired in [false, true] {
        if retired {
            retire(&acl, r_sent, "p02-sent", "p02").await?;
        }
        let t = if retired { "retired" } else { "live" };
        let label = format!("p02.{run}.legacy-direct.sent-{t}.isAllowed.control");
        let req = rh.p02_insert(db, r_sent).await?;
        sqlx::query("UPDATE user_decryption_requests SET already_sent = TRUE WHERE decryption_id = $1")
            .bind(req.id.as_le_slice())
            .execute(db)
            .await?;
        let (kms, task, cancel) = rh.p02_start(db, &req, &label, &cfg).await?;
        let res = p02_finish(db, req.id, &kms, task, cancel, &cfg).await;
        if !retired {
            
        }
        let expect = if retired { Outcome::Rejected } else { Outcome::Forwarded };
        // Already sent: the worker only polls (GetUserDecryptionResult), so a forward is one KMS-mock hit.
        p02_log(&label, &format!("already-sent-{t}"), expect, &res, 1, "already_sent=true", &mut mismatches);
    }

    info!("P02-SUMMARY version={VERSION} run={run} mismatches={}", mismatches.len());
    ensure!(mismatches.is_empty(), "P0.2 cases differ from the expectation: {mismatches:#?}");
    Ok(())
}
